problems = [{'id': 'DRAGON-50', 'title': 'Tính #9: Phép Chia Kết Hợp', 'chapter': 'Phần I. Nhập - Xuất & Phép toán', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 50 trong Bí kíp luyện rồng:\n\nNhập vào 4 số nguyên $a, b, c, d$. Hãy tính và in ra giá trị của biểu thức: $\\frac{\\frac{a}{b} \\times c}{d}$.\n\nKết quả làm tròn chính xác đến 2 chữ số thập phân.', 'input_format': 'Bốn số nguyên $a, b, c, d$ cách nhau bởi dấu cách ($-1000 \\le a, b, c, d \\le 1000; b \\ne 0, d \\ne 0$).', 'output_format': 'In ra kết quả làm tròn đến 2 chữ số thập phân (định dạng `%.2f`).', 'constraints': '$b, d \\ne 0$; $-1000 \\le a, b, c, d \\le 1000$.', 'sample_input': '6 4 1 5', 'sample_output': '0.30', 'hints': 'Dùng kiểu số thực `double` trong C và `float` trong Python để tránh phép chia nguyên.', 'python_starter': "# Bí kíp luyện rồng - Bài 50: Tính #9\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 50: Tính #9\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    parts = sys.stdin.read().split()\n    if len(parts) >= 4:\n        a, b, c, d = map(float, parts[:4])\n        res = ((a / b) * c) / d\n        print(f"{res:.2f}")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n\nint main() {\n    double a, b, c, d;\n    if (scanf("%lf %lf %lf %lf", &a, &b, &c, &d) == 4) {\n        double res = ((a / b) * c) / d;\n        printf("%.2f\\n", res);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Thực hiện tuần tự các phép toán theo số thực: `res = ((a / b) * c) / d`.\n- Chú ý ép kiểu sang số thực để tránh phép chia nguyên (trong C nếu chia 2 số int sẽ bị làm tròn xuống).', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Ví dụ sách)', 'input_data': '6 4 1 5\n', 'expected_output': '0.30\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2', 'input_data': '10 2 3 5\n', 'expected_output': '3.00\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (a = 0)', 'input_data': '0 5 10 2\n', 'expected_output': '0.00\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test biên số âm', 'input_data': '-6 4 1 5\n', 'expected_output': '-0.30\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test giá trị lớn', 'input_data': '1000 3 500 7\n', 'expected_output': '23809.52\n'}]}, {'id': 'DRAGON-51', 'title': 'Rút Gọn Phân Số', 'chapter': 'Phần I. Phép toán & Thuật toán Euclid', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 51 trong Bí kíp luyện rồng:\n\nNhập vào 2 số nguyên $a, b$ ($b \\ne 0$). Hãy in ra hai số nguyên $a_1, b_1$ là tử số và mẫu số của phân số $a/b$ sau khi đã rút gọn tối giản.\n\nChú ý: Mẫu số của phân số tối giản phải là số dương ($b_1 > 0$). Hai số in cách nhau đúng 1 dấu cách.', 'input_format': 'Hai số nguyên $a$ và $b$ nằm trong khoảng $[-10^6, 10^6]$ ($b \\ne 0$).', 'output_format': 'In ra $a_1$ và $b_1$ cách nhau 1 khoảng trắng.', 'constraints': '$-10^6 \\le a, b \\le 10^6$; $b \\ne 0$.', 'sample_input': '60 40', 'sample_output': '3 2', 'hints': 'Tìm ước chung lớn nhất (UCLN/GCD) của $|a|$ và $|b|$, sau đó chia cả tử và mẫu cho GCD. Nếu mẫu $b < 0$, đổi dấu cả tử và mẫu.', 'python_starter': "# Bí kíp luyện rồng - Bài 51: Rút Gọn\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 51: Rút Gọn\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\nimport math\n\ndef solve():\n    parts = sys.stdin.read().split()\n    if len(parts) >= 2:\n        a, b = int(parts[0]), int(parts[1])\n        if a == 0:\n            print("0 1")\n            return\n        g = math.gcd(abs(a), abs(b))\n        a //= g\n        b //= g\n        if b < 0:\n            a = -a\n            b = -b\n        print(f"{a} {b}")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n#include <stdlib.h>\n\nlong long gcd(long long a, long long b) {\n    while (b != 0) {\n        long long t = b;\n        b = a % b;\n        a = t;\n    }\n    return a;\n}\n\nint main() {\n    long long a, b;\n    if (scanf("%lld %lld", &a, &b) == 2) {\n        if (a == 0) {\n            printf("0 1\\n");\n            return 0;\n        }\n        long long g = gcd(llabs(a), llabs(b));\n        a /= g;\n        b /= g;\n        if (b < 0) {\n            a = -a;\n            b = -b;\n        }\n        printf("%lld %lld\\n", a, b);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Để rút gọn phân số $a/b$, ta tìm $g = \\gcd(|a|, |b|)$. Khi đó phân số tối giản là $(a/g) / (b/g)$.\n- Quy ước mẫu số luôn dương: nếu $b < 0$, nhân cả tử và mẫu với $-1$.\n- Trường hợp đặc biệt $a = 0$: phân số tối giản là `0 1`.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Ví dụ sách)', 'input_data': '60 40\n', 'expected_output': '3 2\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (Tử nhỏ hơn mẫu)', 'input_data': '15 45\n', 'expected_output': '1 3\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (a = 0)', 'input_data': '0 100\n', 'expected_output': '0 1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test biên (Mẫu số âm)', 'input_data': '10 -25\n', 'expected_output': '-2 5\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test số lớn', 'input_data': '999996 999998\n', 'expected_output': '499998 499999\n'}]}, {'id': 'DRAGON-52', 'title': 'Chu Vi & Diện Tích Hình Chữ Nhật', 'chapter': 'Phần I. Hình học cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 52 trong Bí kíp luyện rồng:\n\nNhập vào độ dài 2 cạnh của hình chữ nhật. Hãy tính chu vi và diện tích của hình chữ nhật đó.\n\nIn ra chu vi và diện tích cách nhau 1 khoảng trắng, kết quả được làm tròn đến chữ số thập phân thứ 2.', 'input_format': 'Hai số thực là độ dài 2 cạnh của hình chữ nhật ($0 \\le a, b \\le 10000$).', 'output_format': 'In ra chu vi và diện tích (làm tròn đến 2 chữ số thập phân, cách nhau 1 dấu cách).', 'constraints': '$0 \\le a, b \\le 10000$.', 'sample_input': '6.5 4.2', 'sample_output': '21.40 27.30', 'hints': 'Chu vi = $(a + b) \\times 2$, Diện tích = $a \\times b$.', 'python_starter': "# Bí kíp luyện rồng - Bài 52: Hình Chữ Nhật\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 52: Hình Chữ Nhật\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    parts = sys.stdin.read().split()\n    if len(parts) >= 2:\n        a, b = float(parts[0]), float(parts[1])\n        cv = (a + b) * 2\n        dt = a * b\n        print(f"{cv:.2f} {dt:.2f}")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n\nint main() {\n    double a, b;\n    if (scanf("%lf %lf", &a, &b) == 2) {\n        double cv = (a + b) * 2.0;\n        double dt = a * b;\n        printf("%.2f %.2f\\n", cv, dt);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Áp dụng công thức hình học cổ điển:\n  $$\\text{Chu vi} = 2 \\times (a + b)$$\n  $$\\text{Diện tích} = a \\times b$$\n- Định dạng làm tròn 2 chữ số sau dấu phẩy bằng `%.2f`.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Mẫu)', 'input_data': '6.5 4.2\n', 'expected_output': '21.40 27.30\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (Số nguyên)', 'input_data': '5 10\n', 'expected_output': '30.00 50.00\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (Cạnh bằng 0)', 'input_data': '0 10.5\n', 'expected_output': '21.00 0.00\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test hình vuông', 'input_data': '7.5 7.5\n', 'expected_output': '30.00 56.25\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test cạnh cực đại 10000', 'input_data': '10000 10000\n', 'expected_output': '40000.00 100000000.00\n'}]}, {'id': 'DRAGON-53', 'title': 'Đường Chéo Hình Vuông', 'chapter': 'Phần I. Hình học cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 53 trong Bí kíp luyện rồng:\n\nNhập vào độ dài 1 cạnh của hình vuông. Hãy tính độ dài đường chéo của hình vuông đó.\n\nKết quả làm tròn đến chữ số thập phân thứ 2.', 'input_format': 'Một số thực là độ dài cạnh hình vuông ($0 \\le a \\le 10000$).', 'output_format': 'In ra độ dài đường chéo làm tròn đến 2 chữ số thập phân.', 'constraints': '$0 \\le a \\le 10000$.', 'sample_input': '6.5', 'sample_output': '9.19', 'hints': 'Định lý Pytago: Đường chéo $d = \\sqrt{a^2 + a^2} = a \\times \\sqrt{2}$.', 'python_starter': "# Bí kíp luyện rồng - Bài 53: Đường Chéo\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 53: Đường Chéo\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\nimport math\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if line:\n        a = float(line)\n        d = a * math.sqrt(2)\n        print(f"{d:.2f}")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n#include <math.h>\n\nint main() {\n    double a;\n    if (scanf("%lf", &a) == 1) {\n        double d = a * sqrt(2.0);\n        printf("%.2f\\n", d);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Đường chéo hình vuông cạnh $a$ bằng $a \\times \\sqrt{2}$.\n- Thư viện `math` cung cấp hàm `sqrt(2)`.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Mẫu: 6.5)', 'input_data': '6.5\n', 'expected_output': '9.19\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (Cạnh 1)', 'input_data': '1\n', 'expected_output': '1.41\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (a = 0)', 'input_data': '0\n', 'expected_output': '0.00\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test cạnh 10', 'input_data': '10\n', 'expected_output': '14.14\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test cạnh 10000', 'input_data': '10000\n', 'expected_output': '14142.14\n'}]}, {'id': 'DRAGON-54', 'title': 'Phân Tích Thừa Số Nguyên Tố', 'chapter': 'Phần II. Số học & Thừa số', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 54 trong Bí kíp luyện rồng:\n\nNhập vào 1 số nguyên dương $n$ ($1 \\le n \\le 10^9$). Hãy phân tích số $n$ thành tích các thừa số nguyên tố.\n\nIn ra các thừa số nguyên tố cách nhau một dấu cách, theo thứ tự tăng dần.', 'input_format': 'Một số nguyên dương $n$ ($1 \\le n \\le 10^9$).', 'output_format': 'Các thừa số nguyên tố cách nhau 1 khoảng trắng xếp tăng dần.', 'constraints': '$1 \\le n \\le 10^9$.', 'sample_input': '60', 'sample_output': '2 2 3 5', 'hints': 'Duyệt thừa số $i$ từ 2 đến $\\sqrt{n}$. Mỗi khi $n \\% i == 0$, chia liên tục và in $i$.', 'python_starter': "# Bí kíp luyện rồng - Bài 54: Phân Tích #1\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 54: Phân Tích #1\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    factors = []\n    i = 2\n    while i * i <= n:\n        while n % i == 0:\n            factors.append(str(i))\n            n //= i\n        i += 1\n    if n > 1:\n        factors.append(str(n))\n    print(" ".join(factors))\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        int first = 1;\n        for (long long i = 2; i * i <= n; i++) {\n            while (n % i == 0) {\n                if (!first) printf(" ");\n                printf("%lld", i);\n                first = 0;\n                n /= i;\n            }\n        }\n        if (n > 1) {\n            if (!first) printf(" ");\n            printf("%lld", n);\n        }\n        printf("\\n");\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Ta chia dần $n$ cho các số nguyên $i \\ge 2$. Khi nào còn chia hết cho $i$ thì tiếp tục chia và ghi nhận $i$.\n- Chỉ cần duyệt $i$ đến $\\sqrt{n}$. Nếu sau vòng lặp $n > 1$ thì phần dư còn lại chính là một thừa số nguyên tố lớn.\n- Độ phức tạp thời gian: $O(\\sqrt{n})$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Mẫu: 60)', 'input_data': '60\n', 'expected_output': '2 2 3 5\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (Lũy thừa 2)', 'input_data': '16\n', 'expected_output': '2 2 2 2\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (Số nguyên tố)', 'input_data': '13\n', 'expected_output': '13\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test tích hai số nguyên tố', 'input_data': '91\n', 'expected_output': '7 13\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test số lớn 10^9', 'input_data': '1000000000\n', 'expected_output': '2 2 2 2 2 2 2 2 2 5 5 5 5 5 5 5 5 5\n'}]}, {'id': 'DRAGON-55', 'title': 'Số Cách Phân Tích Tổng 2 Số', 'chapter': 'Phần I. Số học cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 55 trong Bí kíp luyện rồng:\n\nNhập vào một số nguyên dương $n$. In ra số cách khác nhau phân tích số $n$ thành tổng 2 số không âm ($a + b = n$ với $0 \\le a \\le b$).', 'input_format': 'Một số nguyên dương $n$ ($1 \\le n \\le 10^9$).', 'output_format': 'In ra 1 số nguyên là số cách phân tích.', 'constraints': '$1 \\le n \\le 10^9$.', 'sample_input': '6', 'sample_output': '4', 'hints': 'Với $n = 6$, các cặp là (0,6), (1,5), (2,4), (3,3) -> có 4 cặp. Công thức tổng quát: $\\lfloor n / 2 \\rfloor + 1$.', 'python_starter': "# Bí kíp luyện rồng - Bài 55: Phân Tích #2\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 55: Phân Tích #2\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if line:\n        n = int(line)\n        print(n // 2 + 1)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        printf("%lld\\n", n / 2 + 1);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Vì $a \\le b$ và $a + b = n$, ta có $2a \\le a + b = n \\implies a \\le n / 2$.\n- $a$ là số không âm nên $a \\in \\{0, 1, 2, \\dots, \\lfloor n/2 \\rfloor\\}$.\n- Vậy có đúng $\\lfloor n/2 \\rfloor + 1$ cách.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Mẫu: 6 -> 4)', 'input_data': '6\n', 'expected_output': '4\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (Số lẻ: 5 -> 3)', 'input_data': '5\n', 'expected_output': '3\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (n = 1)', 'input_data': '1\n', 'expected_output': '1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test n = 2', 'input_data': '2\n', 'expected_output': '2\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test n = 10^9', 'input_data': '1000000000\n', 'expected_output': '500000001\n'}]}, {'id': 'DRAGON-56', 'title': 'Tổng 3 Số Nguyên Liên Tiếp', 'chapter': 'Phần I. Toán học & Điều kiện', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 56 trong Bí kíp luyện rồng:\n\nNhập vào 1 số nguyên dương $n$. Kiểm tra xem số $n$ có thể phân tích thành tổng của 3 số nguyên dương liên tiếp hay không.\n\nIn ra `YES` nếu có thể, ngược lại in ra `NO`.', 'input_format': 'Một số nguyên dương $n$ ($1 \\le n \\le 10^9$).', 'output_format': 'In ra `YES` hoặc `NO`.', 'constraints': '$1 \\le n \\le 10^9$.', 'sample_input': '60', 'sample_output': 'YES', 'hints': 'Ba số liên tiếp có dạng $k-1, k, k+1$. Tổng của chúng là $3k$. Vì các số là số nguyên dương nên $k-1 \\ge 1 \\implies k \\ge 2 \\implies 3k \\ge 6$. Vậy $n \\vdots 3$ và $n \\ge 6$.', 'python_starter': "# Bí kíp luyện rồng - Bài 56: Phân Tích #3\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 56: Phân Tích #3\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if line:\n        n = int(line)\n        if n >= 6 and n % 3 == 0:\n            print("YES")\n        else:\n            print("NO")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        if (n >= 6 && n % 3 == 0) printf("YES\\n");\n        else printf("NO\\n");\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Tổng 3 số nguyên dương liên tiếp: $x + (x+1) + (x+2) = 3x + 3 = 3(x+1)$.\n- Vì $x \\ge 1$ nên $3x + 3 \\ge 6$ và luôn chia hết cho 3.\n- Điều kiện cần và đủ: $n \\ge 6$ và $n \\% 3 == 0$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (60 -> YES)', 'input_data': '60\n', 'expected_output': 'YES\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (35 -> NO)', 'input_data': '35\n', 'expected_output': 'NO\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên nhỏ nhất hợp lệ (6 = 1+2+3)', 'input_data': '6\n', 'expected_output': 'YES\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test bẫy (3 chia hết cho 3 nhưng không đủ 3 số nguyên dương)', 'input_data': '3\n', 'expected_output': 'NO\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test số lớn', 'input_data': '999999999\n', 'expected_output': 'YES\n'}]}, {'id': 'DRAGON-57', 'title': 'Phân Tích #4 (Số Cách Phân Tích Tích)', 'chapter': 'Phần V. Bài toán phân tích & Số học', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào một số nguyên dương $n$. Hãy đếm số cách phân tích số $n$ thành tích của hai số nguyên dương $a$ và $b$ sao cho $a \\le b$ (các cặp $(a, b)$ và $(b, a)$ được coi là một cách giống nhau).', 'input_format': 'Một dòng duy nhất chứa số nguyên dương $n$ ($1 \\le n \\le 10^9$).', 'output_format': 'In ra một số nguyên là số cách phân tích tìm được.', 'constraints': '$1 \\le n \\le 10^9$\nThời gian chạy: 1.5s\nBộ nhớ: 256MB', 'sample_input': '6', 'sample_output': '2', 'hints': 'Mỗi cặp $(a, b)$ tương ứng với một ước số $a \\le \\sqrt{n}$. Lặp $a$ từ 1 đến $\\lfloor\\sqrt{n}\\rfloor$ và kiểm tra $n \\% a == 0$.', 'python_starter': "# Bí kíp luyện rồng - Phân Tích #4\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Phân Tích #4\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\nimport math\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    count = 0\n    limit = math.isqrt(n)\n    for a in range(1, limit + 1):\n        if n % a == 0:\n            count += 1\n    print(count)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <math.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        long long count = 0;\n        long long limit = (long long)sqrt(n);\n        for (long long a = 1; a <= limit; a++) {\n            if (n % a == 0) {\n                count++;\n            }\n        }\n        printf("%lld\\n", count);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- **Ý tưởng:** Cần tìm số cặp $(a, b)$ nguyên dương thỏa mãn $a \\times b = n$ và $a \\le b$. Vì $a \\le b$, ta suy ra $a \\le \\sqrt{n}$. Số lượng cặp $(a, b)$ chính bằng số ước số $a$ của $n$ thỏa mãn $a \\le \\sqrt{n}$.\n- **Độ phức tạp:** Thời gian $O(\\sqrt{n})$ (với $n \\le 10^9$, $\\sqrt{n} \\le 31622$ vòng lặp chạy cực nhanh trong vài ms). Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu)', 'input_data': '6\n', 'expected_output': '2\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Số có nhiều ước', 'input_data': '12\n', 'expected_output': '3\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (n = 1)', 'input_data': '1\n', 'expected_output': '1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Số chính phương (n = 36)', 'input_data': '36\n', 'expected_output': '5\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test (n = 10^9)', 'input_data': '1000000000\n', 'expected_output': '50\n'}]}, {'id': 'DRAGON-58', 'title': 'Phân Tích Tổng Có Tích Lớn Nhất', 'chapter': 'Phần I. Toán học & Tối ưu', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 58 trong Bí kíp luyện rồng:\n\nNhập vào một số nguyên dương $n$. Tìm cách phân tích số $n$ thành tổng 2 số nguyên dương ($a + b = n$ với $1 \\le a \\le b$) sao cho tích $a \\times b$ là lớn nhất.\n\nIn ra 2 số $a$ và $b$ cách nhau 1 dấu cách.', 'input_format': 'Một số nguyên dương $n$ ($2 \\le n \\le 10^9$).', 'output_format': 'In ra 2 số $a$ và $b$ ($a \\le b$).', 'constraints': '$2 \\le n \\le 10^9$.', 'sample_input': '6', 'sample_output': '3 3', 'hints': 'Bất đẳng thức Cauchy: Khi tổng hai số không đổi thì tích đạt giá trị lớn nhất khi hai số đó bằng nhau hoặc gần nhau nhất: $a = \\lfloor n/2 \\rfloor, b = n - a$.', 'python_starter': "# Bí kíp luyện rồng - Bài 58: Phân Tích #5\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 58: Phân Tích #5\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if line:\n        n = int(line)\n        a = n // 2\n        b = n - a\n        print(f"{a} {b}")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        long long a = n / 2;\n        long long b = n - a;\n        printf("%lld %lld\\n", a, b);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Theo BĐT AM-GM, tích $a \\times b$ đạt cực đại khi hiệu $|a - b|$ đạt cực tiểu.\n- Do đó chọn $a = \\lfloor n/2 \\rfloor$ và $b = n - a$.\n- Độ phức tạp: $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Mẫu: 6 -> 3 3)', 'input_data': '6\n', 'expected_output': '3 3\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (Số lẻ: 7 -> 3 4)', 'input_data': '7\n', 'expected_output': '3 4\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên nhỏ nhất (2 -> 1 1)', 'input_data': '2\n', 'expected_output': '1 1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test n = 3 -> 1 2', 'input_data': '3\n', 'expected_output': '1 2\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test số lớn n = 10^9', 'input_data': '1000000000\n', 'expected_output': '500000000 500000000\n'}]}, {'id': 'DRAGON-59', 'title': 'Phân Tích #6 (Tổng Thừa Số Tối Thiểu)', 'chapter': 'Phần V. Bài toán phân tích & Số học', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào một số nguyên dương $n$. Tìm cách phân tích số $n$ thành tích hai số nguyên dương $a \\times b = n$ ($a \\le b$) sao cho tổng hai số $a + b$ là nhỏ nhất (tức hai thừa số gần nhau nhất, như ví dụ trong sách: $6 \\to 2\\ 3$).', 'input_format': 'Một dòng duy nhất chứa số nguyên dương $n$ ($1 \\le n \\le 10^9$).', 'output_format': 'In ra 2 số nguyên dương $a$ và $b$ ($a \\le b$), cách nhau bởi một khoảng trắng.', 'constraints': '$1 \\le n \\le 10^9$\nThời gian chạy: 1.5s\nBộ nhớ: 256MB', 'sample_input': '6', 'sample_output': '2 3', 'hints': 'Cho $a$ chạy lùi từ $\\lfloor\\sqrt{n}\\rfloor$ về 1. Ước $a$ đầu tiên tìm được thỏa mãn $n \\% a == 0$ chính là thừa số lớn nhất $\\le \\sqrt{n}$, cho tổng $a + b$ nhỏ nhất.', 'python_starter': "# Bí kíp luyện rồng - Phân Tích #6\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Phân Tích #6\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\nimport math\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    start = math.isqrt(n)\n    for a in range(start, 0, -1):\n        if n % a == 0:\n            b = n // a\n            print(f"{a} {b}")\n            return\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n#include <math.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        long long start = (long long)sqrt(n);\n        for (long long a = start; a >= 1; a--) {\n            if (n % a == 0) {\n                long long b = n / a;\n                printf("%lld %lld\\n", a, b);\n                return 0;\n            }\n        }\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- **Ý tưởng:** Với tích $a \\times b = n$ cố định, tổng $a + b$ đạt giá trị nhỏ nhất khi $a$ và $b$ gần nhau nhất (tức hiệu $b - a$ nhỏ nhất). Vì $a \\le \\sqrt{n} \\le b$, ta bắt đầu duyệt $a$ từ $\\lfloor\\sqrt{n}\\rfloor$ giảm dần về 1. Ước số $a$ đầu tiên chia hết cho $n$ sẽ cho $a$ lớn nhất có thể và $b = n / a$ nhỏ nhất có thể, tức tổng $a + b$ nhỏ nhất.\n- **Độ phức tạp:** Thời gian $O(\\sqrt{n})$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu)', 'input_data': '6\n', 'expected_output': '2 3\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Số chính phương', 'input_data': '16\n', 'expected_output': '4 4\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (n = 1)', 'input_data': '1\n', 'expected_output': '1 1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Số nguyên tố (n = 13)', 'input_data': '13\n', 'expected_output': '1 13\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test (n = 10^9)', 'input_data': '1000000000\n', 'expected_output': '31250 32000\n'}]}, {'id': 'DRAGON-60', 'title': 'Số Nguyên Tố Lớn Nhất Nhỏ Hơn Hoặc Bằng N', 'chapter': 'Phần II. Vòng lặp & Thuật toán', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 60 trong Bí kíp luyện rồng:\n\nNhập vào 1 số nguyên dương $n$ ($2 \\le n \\le 100000$). In ra số nguyên tố lớn nhất nhỏ hơn hoặc bằng $n$.', 'input_format': 'Một số nguyên dương $n$ ($2 \\le n \\le 100000$).', 'output_format': 'Một số nguyên tố duy nhất thỏa mãn.', 'constraints': '$2 \\le n \\le 100000$.', 'sample_input': '6', 'sample_output': '5', 'hints': 'Duyệt lùi từ $n$ giảm dần về 2, số đầu tiên thỏa mãn là số nguyên tố chính là đáp án cần tìm.', 'python_starter': "# Bí kíp luyện rồng - Bài 60: Nguyên Tố\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 60: Nguyên Tố\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef is_prime(x):\n    if x < 2: return False\n    if x in (2, 3): return True\n    if x % 2 == 0 or x % 3 == 0: return False\n    i = 5\n    while i * i <= x:\n        if x % i == 0 or x % (i + 2) == 0: return False\n        i += 6\n    return True\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if line:\n        n = int(line)\n        for val in range(n, 1, -1):\n            if is_prime(val):\n                print(val)\n                break\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <stdbool.h>\n\nbool is_prime(long long x) {\n    if (x < 2) return false;\n    if (x == 2 || x == 3) return true;\n    if (x % 2 == 0 || x % 3 == 0) return false;\n    for (long long i = 5; i * i <= x; i += 6) {\n        if (x % i == 0 || x % (i + 2) == 0) return false;\n    }\n    return true;\n}\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        for (long long v = n; v >= 2; v--) {\n            if (is_prime(v)) {\n                printf("%lld\\n", v);\n                break;\n            }\n        }\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Lặp $x$ từ $n$ lùi dần về 2. Khi gặp số nguyên tố đầu tiên thì in ra và kết thúc.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Mẫu: 6 -> 5)', 'input_data': '6\n', 'expected_output': '5\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (Chính nó là số nguyên tố: 7 -> 7)', 'input_data': '7\n', 'expected_output': '7\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên nhỏ nhất (2 -> 2)', 'input_data': '2\n', 'expected_output': '2\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test số 10 -> 7', 'input_data': '10\n', 'expected_output': '7\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test n = 100000 -> 99991', 'input_data': '100000\n', 'expected_output': '99991\n'}]}, {'id': 'DRAGON-61', 'title': 'Fibonacci #1 (Số Fibonacci Thứ N)', 'chapter': 'Phần VI. Dãy số & Đệ quy cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Dãy số Fibonacci được định nghĩa như sau: $f(1) = 1, f(2) = 1, f(i) = f(i-1) + f(i-2)$ với mọi $i \\ge 3$.\n\nNhập vào một số nguyên dương $n$. Hãy in ra số Fibonacci thứ $n$.', 'input_format': 'Một dòng duy nhất chứa số nguyên dương $n$ ($1 \\le n \\le 40$).', 'output_format': 'In ra số Fibonacci thứ $n$.', 'constraints': '$1 \\le n \\le 40$\nThời gian chạy: 1.5s\nBộ nhớ: 256MB', 'sample_input': '6', 'sample_output': '8', 'hints': 'Sử dụng mảng hoặc 2 biến để tính tịnh tiến dãy Fibonacci từ $f(1), f(2)$ lên $f(n)$.', 'python_starter': "# Bí kíp luyện rồng - Fibonacci #1\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Fibonacci #1\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    if n <= 2:\n        print(1)\n        return\n    a, b = 1, 1\n    for _ in range(3, n + 1):\n        a, b = b, a + b\n    print(b)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        if (n <= 2) {\n            printf("1\\n");\n            return 0;\n        }\n        long long a = 1, b = 1;\n        for (int i = 3; i <= n; i++) {\n            long long next = a + b;\n            a = b;\n            b = next;\n        }\n        printf("%lld\\n", b);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- **Ý tưởng:** Với $n \\le 40$, giá trị $f(40) = 102334155$ hoàn toàn nằm vừa trong kiểu số nguyên 32-bit (và 64-bit `long long` trong C). Duyệt vòng lặp từ 3 đến $n$ với 2 biến lưu $f(i-2)$ và $f(i-1)$ để cập nhật trong thời gian $O(n)$ và bộ nhớ $O(1)$.\n- **Độ phức tạp:** Thời gian $O(n)$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu)', 'input_data': '6\n', 'expected_output': '8\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test n = 1', 'input_data': '1\n', 'expected_output': '1\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test n = 2', 'input_data': '2\n', 'expected_output': '1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test n = 10', 'input_data': '10\n', 'expected_output': '55\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Biên trên (n = 40)', 'input_data': '40\n', 'expected_output': '102334155\n'}]}, {'id': 'DRAGON-62', 'title': 'Fibonacci #2 (Fibonacci Lớn Nhất Nhỏ Hơn Hoặc Bằng N)', 'chapter': 'Phần VI. Dãy số & Đệ quy cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào một số nguyên dương $n$. Hãy in ra số Fibonacci lớn nhất nhỏ hơn hoặc bằng $n$. Dãy Fibonacci được định nghĩa: $f(1) = 1, f(2) = 1, f(i) = f(i-1) + f(i-2)$.', 'input_format': 'Một dòng duy nhất chứa số nguyên dương $n$ ($1 \\le n \\le 100000$).', 'output_format': 'In ra một số nguyên là số Fibonacci lớn nhất $\\le n$.', 'constraints': '$1 \\le n \\le 100000$\nThời gian chạy: 1.5s\nBộ nhớ: 256MB', 'sample_input': '6', 'sample_output': '5', 'hints': 'Sinh liên tiếp các số Fibonacci $1, 1, 2, 3, 5, 8, ...$ chừng nào số tiếp theo còn $\\le n$.', 'python_starter': "# Bí kíp luyện rồng - Fibonacci #2\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Fibonacci #2\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    a, b = 1, 1\n    while True:\n        c = a + b\n        if c > n:\n            break\n        a, b = b, c\n    print(b if n >= 1 else 0)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        long long a = 1, b = 1;\n        while (1) {\n            long long c = a + b;\n            if (c > n) break;\n            a = b;\n            b = c;\n        }\n        printf("%lld\\n", b);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- **Ý tưởng:** Bắt đầu với $a = 1, b = 1$. Ở mỗi bước, tính $c = a + b$. Nếu $c \\le n$, cập nhật $a = b, b = c$. Khi $c > n$, vòng lặp dừng lại và giá trị $b$ chính là số Fibonacci lớn nhất $\\le n$.\n- **Độ phức tạp:** Thời gian $O(\\log n)$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu)', 'input_data': '6\n', 'expected_output': '5\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test n = 1', 'input_data': '1\n', 'expected_output': '1\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Số đúng bằng số Fibonacci (n = 8)', 'input_data': '8\n', 'expected_output': '8\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test n = 100', 'input_data': '100\n', 'expected_output': '89\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Biên trên (n = 100000)', 'input_data': '100000\n', 'expected_output': '75025\n'}]}, {'id': 'DRAGON-63', 'title': 'Fibonacci #3 (Kiểm Tra Số Fibonacci)', 'chapter': 'Phần VI. Dãy số & Đệ quy cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào một số nguyên dương $n$. Kiểm tra xem $n$ có phải là số thuộc dãy Fibonacci hay không. Biết dãy Fibonacci có $f(1)=1, f(2)=1, f(i)=f(i-1)+f(i-2)$.', 'input_format': 'Một dòng duy nhất chứa số nguyên dương $n$ ($1 \\le n \\le 10^9$).', 'output_format': "In ra 'YES' nếu $n$ là một số Fibonacci, ngược lại in ra 'NO'.", 'constraints': '$1 \\le n \\le 10^9$\nThời gian chạy: 1.5s\nBộ nhớ: 256MB', 'sample_input': '3', 'sample_output': 'YES', 'hints': 'Dãy Fibonacci tăng theo hàm mũ, số Fibonacci $\\le 10^9$ chỉ có khoảng 45 số. Ta có thể sinh dần các số Fibonacci cho đến khi bằng $n$ (YES) hoặc vượt quá $n$ (NO).', 'python_starter': "# Bí kíp luyện rồng - Fibonacci #3\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Fibonacci #3\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    if n == 1:\n        print("YES")\n        return\n    a, b = 1, 1\n    while b < n:\n        a, b = b, a + b\n    if b == n:\n        print("YES")\n    else:\n        print("NO")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        if (n == 1) {\n            printf("YES\\n");\n            return 0;\n        }\n        long long a = 1, b = 1;\n        while (b < n) {\n            long long c = a + b;\n            a = b;\n            b = c;\n        }\n        if (b == n) {\n            printf("YES\\n");\n        } else {\n            printf("NO\\n");\n        }\n    }\n    return 0;\n}', 'editorial': "### Phân Tích & Hướng Dẫn Giải\n- **Ý tưởng:** Ta sinh tuần tự các phần tử của dãy Fibonacci xuất phát từ $f(1)=1, f(2)=1$. Chừng nào số hiện tại $b < n$, ta tiếp tục cộng số tiếp theo. Nếu dừng lại tại $b == n$ thì kết luận 'YES', ngược lại nếu $b > n$ thì 'NO'.\n- **Độ phức tạp:** Thời gian $O(\\log n)$ (tối đa ~50 bước lặp), Bộ nhớ $O(1)$.", 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu 1)', 'input_data': '3\n', 'expected_output': 'YES\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test không phải Fibo (Mẫu 2)', 'input_data': '9\n', 'expected_output': 'NO\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test n = 1', 'input_data': '1\n', 'expected_output': 'YES\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Fibo lớn (n = 55)', 'input_data': '55\n', 'expected_output': 'YES\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Số lớn không phải Fibo', 'input_data': '1000000000\n', 'expected_output': 'NO\n'}]}, {'id': 'DRAGON-64', 'title': 'Đếm Số Chữ Số Của N', 'chapter': 'Phần II. Xử lý số học', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 64 trong Bí kíp luyện rồng:\n\nNhập vào 1 số nguyên dương $n$ ($1 \\le n \\le 10^9$). Hãy đếm và in ra số lượng chữ số của $n$.', 'input_format': 'Một số nguyên dương $n$ ($1 \\le n \\le 10^9$).', 'output_format': 'In ra một số nguyên duy nhất là số chữ số.', 'constraints': '$1 \\le n \\le 10^9$.', 'sample_input': '346', 'sample_output': '3', 'hints': 'Chia $n$ cho 10 cho đến khi $n = 0$, đếm số bước chia; hoặc chuyển sang chuỗi ký tự rồi lấy độ dài.', 'python_starter': "# Bí kíp luyện rồng - Bài 64: Số Chữ Số\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 64: Số Chữ Số\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    s = sys.stdin.read().strip()\n    if s:\n        print(len(s))\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        int cnt = 0;\n        while (n > 0) {\n            cnt++;\n            n /= 10;\n        }\n        printf("%d\\n", cnt);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Chia $n$ liên tục cho 10 cho đến khi bằng 0, mỗi lần chia tăng biến đếm lên 1.\n- Độ phức tạp thời gian: $O(\\log_{10} n)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (Mẫu: 346 -> 3)', 'input_data': '346\n', 'expected_output': '3\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (1 chữ số)', 'input_data': '7\n', 'expected_output': '1\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (10 -> 2)', 'input_data': '10\n', 'expected_output': '2\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test 5 chữ số', 'input_data': '12345\n', 'expected_output': '5\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test 10^9 (10 chữ số)', 'input_data': '1000000000\n', 'expected_output': '10\n'}]}, {'id': 'DRAGON-65', 'title': 'Tính Tổng Các Chữ Số', 'chapter': 'Phần II. Xử lý số học', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 65 trong Bí kíp luyện rồng:\n\nNhập vào 1 số nguyên dương $n$ ($1 \\le n \\le 10^9$). Hãy tính và in ra tổng tất cả các chữ số của $n$.', 'input_format': 'Một số nguyên dương $n$ ($1 \\le n \\le 10^9$).', 'output_format': 'In ra một số nguyên duy nhất là tổng các chữ số.', 'constraints': '$1 \\le n \\le 10^9$.', 'sample_input': '346', 'sample_output': '13', 'hints': 'Lấy chữ số cuối cùng bằng `n % 10`, cộng vào tổng, rồi bỏ chữ số cuối bằng `n // 10`.', 'python_starter': "# Bí kíp luyện rồng - Bài 65: Tổng Chữ Số\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 65: Tổng Chữ Số\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    s = sys.stdin.read().strip()\n    if s:\n        print(sum(int(ch) for ch in s if ch.isdigit()))\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        long long sum = 0;\n        while (n > 0) {\n            sum += (n % 10);\n            n /= 10;\n        }\n        printf("%lld\\n", sum);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Sử dụng vòng lặp: `sum += n % 10; n /= 10;`\n- Lặp lại cho đến khi `n == 0`.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (346 -> 13)', 'input_data': '346\n', 'expected_output': '13\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (1 số)', 'input_data': '9\n', 'expected_output': '9\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test toàn số 0 (1000 -> 1)', 'input_data': '1000\n', 'expected_output': '1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test đối xứng 12321 -> 9', 'input_data': '12321\n', 'expected_output': '9\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test 999999999 -> 81', 'input_data': '999999999\n', 'expected_output': '81\n'}]}, {'id': 'DRAGON-66', 'title': 'Trung Bình Cộng Chữ Số', 'chapter': 'Phần VII. Xử lý chữ số', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào một số nguyên dương $n$. Hãy tính và in ra trung bình cộng các chữ số của $n$. Kết quả được làm tròn đến đúng 2 chữ số thập phân.', 'input_format': 'Một dòng duy nhất chứa số nguyên dương $n$ ($1 \\le n \\le 10^9$).', 'output_format': 'In ra giá trị trung bình cộng làm tròn đến 2 chữ số thập phân (định dạng `%.2f`).', 'constraints': '$1 \\le n \\le 10^9$\nThời gian chạy: 1.5s\nBộ nhớ: 256MB', 'sample_input': '346', 'sample_output': '4.33', 'hints': 'Tách từng chữ số của $n$ qua phép chia dư $n \\% 10$ và chia nguyên $n // 10$, tính tổng và đếm số lượng chữ số, sau đó chia lấy trung bình.', 'python_starter': "# Bí kíp luyện rồng - Trung Bình Cộng Chữ Số\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Trung Bình Cộng Chữ Số\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': 'import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    digits = [int(c) for c in line if c.isdigit()]\n    if digits:\n        avg = sum(digits) / len(digits)\n        print(f"{avg:.2f}")\n\nif __name__ == \'__main__\':\n    solve()', 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        long long sum = 0;\n        int count = 0;\n        while (n > 0) {\n            sum += (n % 10);\n            count++;\n            n /= 10;\n        }\n        double avg = (double)sum / count;\n        printf("%.2f\\n", avg);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- **Ý tưởng:** Đọc số nguyên $n$. Dùng vòng lặp lấy từng chữ số bằng `n % 10`, cộng vào biến `sum` và tăng biến `count`. Sau khi xử lý hết chữ số, in kết quả `(double)sum / count` với định dạng `%.2f`.\n- **Độ phức tạp:** Thời gian $O(\\log_{10} n)$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu)', 'input_data': '346\n', 'expected_output': '4.33\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Số có chữ số 0', 'input_data': '100\n', 'expected_output': '0.33\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Số có 1 chữ số', 'input_data': '9\n', 'expected_output': '9.00\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Các chữ số giống nhau', 'input_data': '5555\n', 'expected_output': '5.00\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Số đầy đủ 1 đến 9', 'input_data': '123456789\n', 'expected_output': '5.00\n'}]}, {'id': 'DRAGON-67', 'title': 'Số Chữ Số 0 Tận Cùng Của N Giai Thừa (N!)', 'chapter': 'Phần II. Toán học & Giai thừa', 'difficulty': 'Trung bình', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Bài 67 trong Bí kíp luyện rồng:\n\nNhập vào 1 số nguyên dương $n$ ($1 \\le n \\le 10^9$). Hãy in ra số lượng chữ số 0 ở tận cùng của giá trị $n!$ ($n! = 1 \\times 2 \\times 3 \\times \\dots \\times n$).', 'input_format': 'Một số nguyên dương $n$ ($1 \\le n \\le 10^9$).', 'output_format': 'In ra một số nguyên duy nhất là số chữ số 0 ở tận cùng của $n!$.', 'constraints': '$1 \\le n \\le 10^9$.', 'sample_input': '10', 'sample_output': '2', 'hints': 'Số chữ số 0 tận cùng bằng số lần chia hết cho 10 = 2 * 5. Vì số thừa số 2 luôn nhiều hơn thừa số 5, ta chỉ cần đếm số thừa số 5 trong n! bằng công thức Legendre: $\\lfloor n/5 \\rfloor + \\lfloor n/25 \\rfloor + \\lfloor n/125 \\rfloor + \\dots$', 'python_starter': "# Bí kíp luyện rồng - Bài 67: Chữ Số 0 Tận Cùng\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Bài 67: Chữ Số 0 Tận Cùng\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if line:\n        n = int(line)\n        cnt = 0\n        p = 5\n        while n >= p:\n            cnt += n // p\n            p *= 5\n        print(cnt)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    long long n;\n    if (scanf("%lld", &n) == 1) {\n        long long cnt = 0;\n        for (long long p = 5; p <= n; p *= 5) {\n            cnt += n / p;\n        }\n        printf("%lld\\n", cnt);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- Để tạo ra một chữ số 0 ở cuối ta cần một tích $2 \\times 5$.\n- Theo công thức Legendre, số mũ của 5 trong phân tích thừa số nguyên tố của $n!$ là:\n  $$E_5(n!) = \\sum_{k=1}^{\\infty} \\left\\lfloor \\frac{n}{5^k} \\right\\rfloor$$\n- Vòng lặp chỉ tốn $O(\\log_5 n)$ bước, chạy trong dưới $0.001$ giây với $n = 10^9$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản 1 (10! -> 2)', 'input_data': '10\n', 'expected_output': '2\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test cơ bản 2 (5! -> 1)', 'input_data': '5\n', 'expected_output': '1\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên (n < 5 -> 0)', 'input_data': '4\n', 'expected_output': '0\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test n = 25 (có 25 chia hết cho 5^2 -> 6)', 'input_data': '25\n', 'expected_output': '6\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test n = 10^9 (Cực lớn)', 'input_data': '1000000000\n', 'expected_output': '249999998\n'}]}, {'id': 'DRAGON-68', 'title': 'Tận Cùng (Khó) - Chữ Số Khác 0 Cuối Cùng Của N!', 'chapter': 'Phần VII. Xử lý chữ số', 'difficulty': 'Khó', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào một số nguyên dương $n$. Hãy tìm và in ra chữ số tận cùng khác 0 của $n!$ ($n! = 1 \\times 2 \\times 3 \\times \\dots \\times n$).', 'input_format': 'Một dòng duy nhất chứa số nguyên dương $n$ ($1 \\le n \\le 100000$).', 'output_format': 'In ra một chữ số duy nhất là chữ số khác 0 tận cùng của $n!$.', 'constraints': '$1 \\le n \\le 100000$\nThời gian chạy: 1.5s\nBộ nhớ: 256MB', 'sample_input': '10', 'sample_output': '8', 'hints': 'Các số 0 tận cùng được tạo thành bởi tích $2 \\times 5$. Ta đếm số thừa số 2 và 5 rồi triệt tiêu chúng. Phần thừa số 2 dư ra sẽ nhân theo modulo 10.', 'python_starter': "# Bí kíp luyện rồng - Tận Cùng (Khó)\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Tận Cùng (Khó)\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    line = sys.stdin.read().strip()\n    if not line:\n        return\n    n = int(line)\n    if n <= 1:\n        print(1)\n        return\n    ans = 1\n    c2 = 0\n    c5 = 0\n    for i in range(1, n + 1):\n        cur = i\n        while cur % 2 == 0:\n            c2 += 1\n            cur //= 2\n        while cur % 5 == 0:\n            c5 += 1\n            cur //= 5\n        ans = (ans * (cur % 10)) % 10\n    rem2 = c2 - c5\n    ans = (ans * pow(2, rem2, 10)) % 10\n    print(ans)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        if (n <= 1) {\n            printf("1\\n");\n            return 0;\n        }\n        int ans = 1;\n        int c2 = 0, c5 = 0;\n        for (int i = 1; i <= n; i++) {\n            int cur = i;\n            while (cur % 2 == 0) {\n                c2++;\n                cur /= 2;\n            }\n            while (cur % 5 == 0) {\n                c5++;\n                cur /= 5;\n            }\n            ans = (ans * (cur % 10)) % 10;\n        }\n        int rem2 = c2 - c5;\n        for (int i = 0; i < rem2; i++) {\n            ans = (ans * 2) % 10;\n        }\n        printf("%d\\n", ans);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- **Ý tưởng:** Mọi chữ số 0 tận cùng đều xuất phát từ việc nhân thừa số nguyên tố 2 và 5 ($2 \\times 5 = 10$). Do đó, ta phân tích mỗi số từ 1 đến $n$: rút hết thừa số 2 và thừa số 5, đồng thời nhân các phần còn lại theo modulo 10.\n- Vì số lượng thừa số 2 trong $n!$ luôn nhiều hơn số thừa số 5, sau khi ghép cặp triệt tiêu sẽ còn dư lại $(c2 - c5)$ thừa số 2. Ta chỉ cần nhân thêm $2^{(c2 - c5)} \\pmod{10}$ vào kết quả cuối cùng.\n- **Độ phức tạp:** Thời gian $O(n \\log n)$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu n = 10)', 'input_data': '10\n', 'expected_output': '8\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Test nhỏ n = 5 (5! = 120)', 'input_data': '5\n', 'expected_output': '2\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Test biên n = 1', 'input_data': '1\n', 'expected_output': '1\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Test n = 20', 'input_data': '20\n', 'expected_output': '4\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Stress test n = 100', 'input_data': '100\n', 'expected_output': '4\n'}]}, {'id': 'DRAGON-69', 'title': 'Chữ Số Tận Cùng Của Tích Mảng', 'chapter': 'Phần VIII. Mảng một chiều cơ bản', 'difficulty': 'Dễ', 'time_limit': 1.5, 'memory_limit': 256, 'description': 'Nhập vào dãy $A$ có $n$ phần tử. In ra chữ số tận cùng của tích các số trong dãy. Chữ số tận cùng luôn là một chữ số từ 0 đến 9.', 'input_format': 'Dòng 1: Số nguyên dương $n$ ($1 \\le n \\le 100$).\\nDòng 2: $n$ số nguyên $a_i$ ($-100000 \\le a_i \\le 100000$), cách nhau bởi dấu cách.', 'output_format': 'In ra chữ số tận cùng của tích tất cả các số trong dãy.', 'constraints': '$1 \\le n \\le 100$\\n$-100000 \\le a_i \\le 100000$\\nThời gian chạy: 1.5s\\nBộ nhớ: 256MB', 'sample_input': '4\n1 -2 3 4', 'sample_output': '4', 'hints': 'Chữ số tận cùng của tích chỉ phụ thuộc vào chữ số tận cùng của từng phần tử. Tích nhân dồn lấy modulo 10 trên giá trị tuyệt đối.', 'python_starter': "# Bí kíp luyện rồng - Chữ Số Tận Cùng\nimport sys\n\ndef solve():\n    # Nhập dữ liệu và viết thuật toán của bạn tại đây\n    pass\n\nif __name__ == '__main__':\n    solve()\n", 'c_starter': '// Bí kíp luyện rồng - Chữ Số Tận Cùng\n#include <stdio.h>\n\nint main() {\n    // Khai báo biến, nhập dữ liệu và viết thuật toán tại đây\n    \n    return 0;\n}\n', 'solution_python': "import sys\n\ndef solve():\n    tokens = sys.stdin.read().split()\n    if not tokens:\n        return\n    n = int(tokens[0])\n    nums = [int(x) for x in tokens[1:n+1]]\n    prod = 1\n    for x in nums:\n        prod = (prod * abs(x)) % 10\n    print(prod)\n\nif __name__ == '__main__':\n    solve()", 'solution_c': '#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    if (scanf("%d", &n) == 1) {\n        int prod = 1;\n        for (int i = 0; i < n; i++) {\n            long long x;\n            if (scanf("%lld", &x) == 1) {\n                prod = (prod * (abs(x) % 10)) % 10;\n            }\n        }\n        printf("%d\\n", prod);\n    }\n    return 0;\n}', 'editorial': '### Phân Tích & Hướng Dẫn Giải\n- **Ý tưởng:** Chữ số tận cùng của một số nguyên bằng giá trị tuyệt đối của số đó chia lấy dư cho 10. Để tránh tràn số khi nhân mảng, ta nhân dồn và lấy `abs(x) % 10` sau mỗi lượt.\n- **Độ phức tạp:** Thời gian $O(n)$, Bộ nhớ $O(1)$.', 'test_cases': [{'test_index': 1, 'is_sample': True, 'description': 'Test cơ bản (Mẫu)', 'input_data': '4\n1 -2 3 4\n', 'expected_output': '4\n'}, {'test_index': 2, 'is_sample': True, 'description': 'Tích có tận cùng là 0', 'input_data': '3\n2 5 7\n', 'expected_output': '0\n'}, {'test_index': 3, 'is_sample': False, 'description': 'Mảng có 1 phần tử âm', 'input_data': '1\n-9\n', 'expected_output': '9\n'}, {'test_index': 4, 'is_sample': False, 'description': 'Tất cả các số tận cùng là 1', 'input_data': '5\n11 21 31 41 51\n', 'expected_output': '1\n'}, {'test_index': 5, 'is_sample': False, 'description': 'Nhiều số âm đan xen', 'input_data': '6\n-13 27 -33 49 51 -63\n', 'expected_output': '1\n'}]}]
